"""Страница игры «Угадай стиль» для сайта.

Собирает web/public/games/stili.html из шаблона tools/game_stili.tpl.html:
в шаблон подставляются данные стилей и зданий, счётчик Метрики и значок
берутся из web/index.html. Названия и фотографии здания игра читает у API
во время игры; данные стилей и порядок зданий — ниже (по лекции «О стилях», запись 1736).
Запуск: python tools/make_game_stili.py
"""
import json, re, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / 'web/public/games'

# name: (период, метод, повестка, заказчик и экономика, [id зданий]).
STYLES = {
 "Римская архитектура": ("I–IV вв.", "Бетон на вулканическом песке и кирпич; купол без каркаса", "Власть и общественное пространство империи", "Император и казна; рабочая сила армии и рабов", [188]),
 "Готика": ("XII–XVI вв.", "Нервюрный свод, аркбутан, контрфорс", "Свет и вера", "Церковь и город; стройка тянется десятилетиями на пожертвования и налоги", [189]),
 "Ренессанс и барокко": ("XV–XVII вв.", "Купол по геометрии, ордер", "Возвращение античной меры; престиж", "Папа и гильдии (цех шерстяников — Флоренция)", [278, 190]),
 "Инженерия XIX века": ("XIX в.", "Чугун, сталь, стекло, сборка на заводе", "Скорость, вокзалы, всемирные выставки", "Выставочные комитеты, железные дороги, промышленники; серийность — дешевле и быстрее", [191, 192]),
 "Чикагская школа": ("1880–90-е", "Стальной каркас, лифт", "Плотный деловой центр", "Частные инвесторы; цена земли требует высоты", [193]),
 "Модерн": ("1890–1910", "Кривая линия, керамика, кованый металл", "Природа против фабрики", "Состоятельный заказчик-покровитель (Гуэль)", [194]),
 "Бозар и ар-деко": ("1890–1930-е", "Каменная облицовка на каркасе", "Порядок, престиж, «лицо» города", "Государство; корпорации, для которых здание — реклама и вложение", [201, 197]),
 "Ранний модернизм и оболочки": ("1920-е", "Тонкий железобетон, расчёт", "Меньше материала на тот же пролёт", "Государство и фирма-изготовитель; дефицит стали", [195, 196]),
 "Форма из расчёта (рационализм)": ("1930–60-е", "Железобетонная оболочка, сборные элементы, рёбра по линиям усилий", "Экономия материала и рабочих рук; скорость", "Город, выставки, комитет, фабрика; фирма Нерви выигрывала конкурсы ценой", [198, 200, 199, 202, 205, 203, 207, 208, 206]),
 "Структурный экспрессионизм": ("1950–70-е", "Преднапряжённые сети, арки, мачты", "Конструкция как образ эпохи", "Штат и государство; ярмарки и выставки", [204, 212]),
 "Лёгкая архитектура (тросы и ткань)": ("1955–72", "Тросовая сеть, ткань, найденная моделью форма", "Лёгкость и открытое общество (Отто)", "Садовые выставки, Экспо, Олимпиада; временные постройки", [213]),
 "Технологический футуризм": ("1960-е", "Геодезическая решётка из стержней", "Больше с меньшим (Фуллер)", "Государство США, Экспо-67", [211]),
 "Брутализм": ("1950–70-е", "Монолитный бетон в опалубке", "Честность материала; массовое строительство", "Государство, Олимпиада-80, ведомства; бетон и местный труд дешевле стали", [214, 215, 216, 217, 210]),
 "Метаболизм": ("1960-е", "Железобетон и сталь, подвесная кровля", "Послевоенное обновление Японии", "Государство, Олимпиада-64", [209]),
 "Конструктивизм и советская классика": ("1920–40-е", "Железобетон, стальные фермы, купол", "Новый общественный заказ", "Государство, пятилетний план", [38]),
 "Постмодерн": ("1970–90-е", "Любые; метод служит образу", "Смысл, ирония, знак", "Частная корпорация; здание как реклама и сборы", [48]),
 "Параметризм": ("2000-е", "Алгоритм, Rhino, Grasshopper", "Общей повестки нет", "Город или частная фирма; репутация и бренд", [49]),
}
# id: (год, 1 — начало стройки, 0 — открытие). Только записи, видимые гостю.
YEARS = {188: (128, 0), 189: (1248, 1), 278: (1436, 0), 190: (1590, 0), 191: (1851, 0), 192: (1889, 0), 193: (1891, 1), 194: (1898, 1), 201: (1918, 0), 197: (1931, 0), 195: (1923, 0), 196: (1923, 0), 198: (1930, 1), 200: (1935, 0), 199: (1933, 1), 202: (1949, 0), 205: (1957, 0), 203: (1953, 0), 207: (1958, 0), 208: (1961, 0), 206: (1958, 0), 204: (1952, 0), 212: (1970, 0), 213: (1972, 0), 211: (1967, 0), 214: (1972, 1), 215: (1979, 0), 216: (1980, 0), 217: (1980, 0), 210: (1967, 0), 209: (1964, 0), 38: (1931, 1), 48: (2023, 0), 49: (2016, 0)}
ALSO = {}

styles = [{"name": n, "period": v[0], "method": v[1], "agenda": v[2], "customer": v[3], "ids": v[4]} for n, v in STYLES.items()]
of = {i: s["name"] for s in styles for i in s["ids"]}
buildings = sorted(({"id": i, "year": y, "start": bool(st), "style": of[i], "also": ALSO.get(i, [])} for i, (y, st) in YEARS.items()),
                   key=lambda b: (b["year"], b["id"]))
assert set(YEARS) == set(of), set(YEARS) ^ set(of)

tpl = (ROOT / 'web/index.html').read_text(encoding='utf-8')
a = tpl.index('    <!-- Yandex.Metrika counter -->')
b = tpl.index('    <!-- /Yandex.Metrika counter -->') + len('    <!-- /Yandex.Metrika counter -->')
fav = re.search(r'    <link rel="icon".*?\n    <link rel="apple-touch-icon"[^\n]*', tpl, re.S).group(0)
page = (ROOT / 'tools/game_stili.tpl.html').read_text(encoding='utf-8')
page = page.replace('/*DATA*/', json.dumps({"styles": styles, "buildings": buildings}, ensure_ascii=False)) \
           .replace('<!--METRIKA-->', tpl[a:b]).replace('<!--FAV-->', fav)
OUT.mkdir(parents=True, exist_ok=True)
(OUT / 'stili.html').write_text(page, encoding='utf-8')
print(len(buildings), 'зданий,', len(styles), 'стилей')
